@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-elevated: #222222;
  --bg-card: #1c1c1c;
  --red: #E63946;
  --red-dark: #c5303c;
  --red-glow: rgba(230, 57, 70, 0.25);
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #2a2a2a;
  --font-heading: 'Barlow Condensed', sans-serif;
  --font-body: 'Inter', sans-serif;
  --max-width: 1200px;
  --transition: 250ms ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--gray-300);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  font-weight: 700;
  text-transform: uppercase;
  color: var(--white);
  letter-spacing: 0.02em;
  line-height: 1.1;
}

/* ===== TOP PROMO BAR ===== */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 24px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--white);
  letter-spacing: 0.04em;
}
.promo-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 700;
}
.promo-bar a:hover { opacity: 0.85; }

/* ===== NAVBAR ===== */
.navbar {
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid var(--gray-800);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  font-weight: 900;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.nav-logo span { color: var(--red); }

.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--gray-400);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: var(--white); }
.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--red);
}

.nav-cta {
  display: flex;
  gap: 12px;
  align-items: center;
}

.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  padding: 8px;
}
.nav-hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 14px 32px;
  border-radius: 4px;
  transition: all var(--transition);
  min-height: 48px;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
}
.btn-primary:hover {
  background: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}
.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--bg-primary);
}
.btn-ghost {
  background: transparent;
  color: var(--gray-400);
  border: 1px solid var(--gray-700);
}
.btn-ghost:hover {
  border-color: var(--white);
  color: var(--white);
}
.btn-sm { padding: 10px 20px; font-size: 0.8rem; min-height: 40px; }
.btn-lg { padding: 18px 48px; font-size: 1.1rem; }

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: linear-gradient(135deg, var(--bg-primary) 0%, #1a0a0c 50%, var(--bg-primary) 100%);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, var(--red-glow) 0%, transparent 60%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 700px;
}
.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--red);
  border: 1px solid var(--red);
  padding: 6px 16px;
  margin-bottom: 24px;
}
.hero h1 {
  font-size: clamp(3rem, 7vw, 5.5rem);
  font-weight: 900;
  line-height: 0.95;
  margin-bottom: 24px;
}
.hero h1 .accent { color: var(--red); }
.hero p {
  font-size: 1.15rem;
  color: var(--gray-300);
  margin-bottom: 36px;
  max-width: 540px;
  line-height: 1.7;
}
.hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }

.hero-page {
  min-height: 50vh;
  background: linear-gradient(180deg, var(--bg-primary) 0%, #1a0a0c 100%);
}
.hero-page h1 { font-size: clamp(2.5rem, 5vw, 4rem); }

/* ===== SECTION STYLES ===== */
.section {
  padding: 100px 0;
}
.section-dark { background: var(--bg-secondary); }
.section-header {
  text-align: center;
  margin-bottom: 64px;
}
.section-header h2 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 1.05rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
}
.section-label {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--red);
  margin-bottom: 12px;
}

/* ===== COMMUNITY PROMO ===== */
.community-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.community-image {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--bg-elevated) 0%, #2a1215 100%);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.community-image::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 1px solid rgba(230, 57, 70, 0.15);
  border-radius: 8px;
}
.community-image svg {
  width: 80px;
  height: 80px;
  opacity: 0.3;
}
.community-text h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 20px;
}
.community-text p {
  color: var(--gray-400);
  font-size: 1.05rem;
  margin-bottom: 32px;
  line-height: 1.7;
}

/* ===== TWO WAYS ===== */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: var(--gray-700); }
.way-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(230, 57, 70, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}
.way-card-icon svg { width: 28px; height: 28px; color: var(--red); }
.way-card h3 { font-size: 1.6rem; margin-bottom: 16px; }
.way-card p {
  color: var(--gray-400);
  line-height: 1.7;
  margin-bottom: 28px;
}

/* ===== STUDIO EXPERIENCE ===== */
.studio-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.studio-visual {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #1a0a0c, var(--bg-elevated));
  border-radius: 8px;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.studio-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, var(--red-glow), transparent 70%);
}
.studio-visual svg { width: 64px; height: 64px; opacity: 0.4; position: relative; z-index: 1; }
.studio-text h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 20px;
}
.studio-text p { color: var(--gray-400); line-height: 1.7; margin-bottom: 32px; }

/* ===== FREE TRIAL CTA ===== */
.trial-section {
  background: linear-gradient(135deg, #2a0a0e 0%, var(--bg-primary) 50%, #1a0a0c 100%);
  text-align: center;
  padding: 120px 0;
  position: relative;
}
.trial-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--red-glow), transparent 60%);
  pointer-events: none;
}
.trial-content {
  position: relative;
  z-index: 1;
}
.trial-section h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 900;
  margin-bottom: 20px;
}
.trial-section p {
  font-size: 1.1rem;
  color: var(--gray-400);
  margin-bottom: 40px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== CAROUSEL ===== */
.carousel-section { overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  transition: transform 500ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.carousel-slide {
  min-width: 33.333%;
  padding: 0 12px;
}
.carousel-slide-inner {
  aspect-ratio: 3/4;
  background: var(--bg-elevated);
  border-radius: 8px;
  overflow: hidden;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-slide-inner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.6) 100%);
}
.carousel-slide-inner svg { width: 48px; height: 48px; opacity: 0.2; }
.carousel-label {
  position: absolute;
  bottom: 16px;
  left: 16px;
  right: 16px;
  z-index: 2;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--white);
  letter-spacing: 0.04em;
}
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 1px solid var(--gray-700);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-btn svg { width: 20px; height: 20px; }
.carousel-dots {
  display: flex;
  align-items: center;
  gap: 8px;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-700);
  border: none;
  transition: all var(--transition);
  cursor: pointer;
  padding: 0;
}
.carousel-dot.active {
  background: var(--red);
  width: 24px;
  border-radius: 4px;
}

/* ===== NEWSLETTER ===== */
.newsletter-section {
  background: var(--bg-secondary);
  border-top: 1px solid var(--gray-800);
  border-bottom: 1px solid var(--gray-800);
}
.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 48px;
}
.newsletter-text h3 {
  font-size: 1.6rem;
  margin-bottom: 8px;
}
.newsletter-text p {
  color: var(--gray-400);
  font-size: 0.95rem;
}
.newsletter-form {
  display: flex;
  gap: 12px;
  flex: 0 0 auto;
}
.newsletter-form input {
  font-family: var(--font-body);
  font-size: 0.95rem;
  padding: 14px 20px;
  background: var(--bg-primary);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  color: var(--white);
  width: 320px;
  min-height: 48px;
  transition: border-color var(--transition);
}
.newsletter-form input:focus {
  outline: none;
  border-color: var(--red);
}
.newsletter-form input::placeholder { color: var(--gray-500); }
.newsletter-form .form-group { position: relative; }
.newsletter-error {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  font-size: 0.8rem;
  color: var(--red);
  margin-top: 4px;
}
.newsletter-success {
  display: none;
  align-items: center;
  gap: 8px;
  font-size: 0.95rem;
  color: #22c55e;
  font-weight: 500;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-primary);
  padding: 80px 0 40px;
  border-top: 1px solid var(--gray-800);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; }
.footer-brand p {
  color: var(--gray-500);
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 280px;
}
.footer h4 {
  font-size: 0.85rem;
  letter-spacing: 0.12em;
  margin-bottom: 20px;
  color: var(--white);
}
.footer-links a {
  display: block;
  color: var(--gray-500);
  font-size: 0.9rem;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--white); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid var(--gray-800);
  font-size: 0.85rem;
  color: var(--gray-500);
}
.country-select {
  font-family: var(--font-body);
  background: var(--bg-secondary);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  color: var(--gray-300);
  padding: 8px 16px;
  font-size: 0.85rem;
  cursor: pointer;
  min-height: 40px;
}
.country-select:focus { outline: none; border-color: var(--red); }

/* ===== TOGGLE (Workout page) ===== */
.toggle-container { display: flex; justify-content: center; margin-bottom: 48px; }
.toggle-group {
  display: inline-flex;
  background: var(--bg-secondary);
  border: 1px solid var(--gray-800);
  border-radius: 6px;
  overflow: hidden;
}
.toggle-btn {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 14px 40px;
  background: transparent;
  color: var(--gray-400);
  transition: all var(--transition);
  min-height: 48px;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}
.toggle-btn:hover:not(.active) { color: var(--white); }

.toggle-content { display: none; animation: fadeIn 300ms ease; }
.toggle-content.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== SCHEDULE TABLE ===== */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}
.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  text-align: left;
  padding: 16px 24px;
  border-bottom: 2px solid var(--gray-800);
}
.schedule-table tbody td {
  padding: 18px 24px;
  border-bottom: 1px solid var(--gray-800);
  color: var(--gray-300);
}
.schedule-table tbody tr:hover { background: rgba(230, 57, 70, 0.05); }
.schedule-table .day-name {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  text-transform: uppercase;
  color: var(--white);
}
.schedule-table .muscle-tag {
  display: inline-block;
  background: rgba(230, 57, 70, 0.1);
  color: var(--red);
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 12px;
  border-radius: 4px;
}

/* ===== INSTRUCTOR GRID ===== */
.filter-bar {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 10px 24px;
  background: transparent;
  color: var(--gray-400);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  transition: all var(--transition);
  min-height: 44px;
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--gray-700);
  transform: translateY(-4px);
}
.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-elevated), #2a1215);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.instructor-photo::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.5) 100%);
}
.instructor-photo svg { width: 48px; height: 48px; opacity: 0.25; }
.instructor-info { padding: 20px; }
.instructor-info h3 {
  font-size: 1.1rem;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.instructor-info .location {
  font-size: 0.85rem;
  color: var(--gray-500);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.instructor-info .location svg { width: 14px; height: 14px; }
.instructor-info .btn { width: 100%; font-size: 0.8rem; padding: 10px; }
.instructor-card.hidden {
  display: none;
}

/* ===== FAQ ACCORDION ===== */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--gray-800);
}
.faq-question {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--white);
  background: none;
  width: 100%;
  text-align: left;
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: color var(--transition);
  min-height: 48px;
}
.faq-question:hover { color: var(--red); }
.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
  color: var(--gray-500);
}
.faq-item.active .faq-question svg { transform: rotate(45deg); color: var(--red); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 0 24px;
  color: var(--gray-400);
  line-height: 1.7;
}

/* ===== FEATURES (Digital page) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  padding: 40px 32px;
  transition: all var(--transition);
  position: relative;
}
.feature-card:hover {
  border-color: var(--gray-700);
  transform: translateY(-2px);
}
.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(230, 57, 70, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}
.feature-icon svg { width: 28px; height: 28px; color: var(--red); }
.feature-card h3 { font-size: 1.2rem; margin-bottom: 12px; }
.feature-card p { color: var(--gray-400); line-height: 1.7; font-size: 0.95rem; }

/* ===== METHOD OVERVIEW ===== */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.method-text h2 { font-size: clamp(2rem, 3.5vw, 3rem); margin-bottom: 20px; }
.method-text p { color: var(--gray-400); line-height: 1.7; margin-bottom: 24px; }
.method-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 32px;
}
.stat-item { text-align: center; }
.stat-number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--red);
  line-height: 1;
}
.stat-label {
  font-size: 0.8rem;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 4px;
}
.method-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1a0a0c, var(--bg-elevated));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.method-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, var(--red-glow), transparent 70%);
  border-radius: 8px;
}

/* ===== TOGGLE CONTENT CARDS ===== */
.toggle-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.toggle-card-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--bg-elevated), #2a1215);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.toggle-card-visual svg { width: 64px; height: 64px; opacity: 0.3; }
.toggle-card-text h3 { font-size: 1.8rem; margin-bottom: 16px; }
.toggle-card-text p { color: var(--gray-400); line-height: 1.7; font-size: 1.05rem; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta .btn-ghost { display: none; }
  .nav-hamburger { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--gray-800);
    padding: 24px;
    gap: 16px;
    z-index: 999;
  }

  .hero { min-height: 70vh; }
  .section { padding: 64px 0; }

  .community-section,
  .studio-grid,
  .two-ways-grid,
  .method-grid,
  .toggle-card { grid-template-columns: 1fr; gap: 32px; }

  .instructor-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .features-grid { grid-template-columns: 1fr; }

  .carousel-slide { min-width: 80%; }

  .newsletter-inner { flex-direction: column; text-align: center; gap: 24px; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .newsletter-form input { width: 100%; }

  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }

  .trial-section { padding: 80px 0; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 2.5rem; }
  .carousel-slide { min-width: 90%; }
  .method-stats { grid-template-columns: repeat(3, 1fr); gap: 12px; }
  .stat-number { font-size: 1.8rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
  .carousel-track { transition: none; }
}

:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}

@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-elevated: #222222;
  --bg-card: #1c1c1c;
  --red: #E63946;
  --red-dark: #c5303c;
  --red-glow: rgba(230, 57, 70, 0.25);
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #2a2a2a;
  --font-heading: 'Barlow Condensed', sans-serif;
  --font-body: 'Inter', sans-serif;
  --max-width: 1200px;
  --transition: 250ms ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--gray-300);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  font-weight: 700;
  text-transform: uppercase;
  color: var(--white);
  letter-spacing: 0.02em;
  line-height: 1.1;
}

/* ===== TOP PROMO BAR ===== */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 24px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--white);
  letter-spacing: 0.04em;
}
.promo-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 700;
}
.promo-bar a:hover { opacity: 0.85; }

/* ===== NAVBAR ===== */
.navbar {
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid var(--gray-800);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  font-weight: 900;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.nav-logo span { color: var(--red); }

.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--gray-400);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: var(--white); }
.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--red);
}

.nav-cta {
  display: flex;
  gap: 12px;
  align-items: center;
}

.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  padding: 8px;
}
.nav-hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 14px 32px;
  border-radius: 4px;
  transition: all var(--transition);
  min-height: 48px;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
}
.btn-primary:hover {
  background: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}
.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--bg-primary);
}
.btn-ghost {
  background: transparent;
  color: var(--gray-400);
  border: 1px solid var(--gray-700);
}
.btn-ghost:hover {
  border-color: var(--white);
  color: var(--white);
}
.btn-sm { padding: 10px 20px; font-size: 0.8rem; min-height: 40px; }
.btn-lg { padding: 18px 48px; font-size: 1.1rem; }

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: linear-gradient(135deg, var(--bg-primary) 0%, #1a0a0c 50%, var(--bg-primary) 100%);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, var(--red-glow) 0%, transparent 60%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 700px;
}
.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--red);
  border: 1px solid var(--red);
  padding: 6px 16px;
  margin-bottom: 24px;
}
.hero h1 {
  font-size: clamp(3rem, 7vw, 5.5rem);
  font-weight: 900;
  line-height: 0.95;
  margin-bottom: 24px;
}
.hero h1 .accent { color: var(--red); }
.hero p {
  font-size: 1.15rem;
  color: var(--gray-300);
  margin-bottom: 36px;
  max-width: 540px;
  line-height: 1.7;
}
.hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }

.hero-page {
  min-height: 50vh;
  background: linear-gradient(180deg, var(--bg-primary) 0%, #1a0a0c 100%);
}
.hero-page h1 { font-size: clamp(2.5rem, 5vw, 4rem); }

/* ===== SECTION STYLES ===== */
.section {
  padding: 100px 0;
}
.section-dark { background: var(--bg-secondary); }
.section-header {
  text-align: center;
  margin-bottom: 64px;
}
.section-header h2 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 1.05rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
}
.section-label {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--red);
  margin-bottom: 12px;
}

/* ===== COMMUNITY PROMO ===== */
.community-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.community-image {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--bg-elevated) 0%, #2a1215 100%);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.community-image::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 1px solid rgba(230, 57, 70, 0.15);
  border-radius: 8px;
}
.community-image svg {
  width: 80px;
  height: 80px;
  opacity: 0.3;
}
.community-text h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 20px;
}
.community-text p {
  color: var(--gray-400);
  font-size: 1.05rem;
  margin-bottom: 32px;
  line-height: 1.7;
}

/* ===== TWO WAYS ===== */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: var(--gray-700); }
.way-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(230, 57, 70, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}
.way-card-icon svg { width: 28px; height: 28px; color: var(--red); }
.way-card h3 { font-size: 1.6rem; margin-bottom: 16px; }
.way-card p {
  color: var(--gray-400);
  line-height: 1.7;
  margin-bottom: 28px;
}

/* ===== STUDIO EXPERIENCE ===== */
.studio-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.studio-visual {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #1a0a0c, var(--bg-elevated));
  border-radius: 8px;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.studio-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, var(--red-glow), transparent 70%);
}
.studio-visual svg { width: 64px; height: 64px; opacity: 0.4; position: relative; z-index: 1; }
.studio-text h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 20px;
}
.studio-text p { color: var(--gray-400); line-height: 1.7; margin-bottom: 32px; }

/* ===== FREE TRIAL CTA ===== */
.trial-section {
  background: linear-gradient(135deg, #2a0a0e 0%, var(--bg-primary) 50%, #1a0a0c 100%);
  text-align: center;
  padding: 120px 0;
  position: relative;
}
.trial-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--red-glow), transparent 60%);
  pointer-events: none;
}
.trial-content {
  position: relative;
  z-index: 1;
}
.trial-section h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 900;
  margin-bottom: 20px;
}
.trial-section p {
  font-size: 1.1rem;
  color: var(--gray-400);
  margin-bottom: 40px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== CAROUSEL ===== */
.carousel-section { overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  transition: transform 500ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.carousel-slide {
  min-width: 33.333%;
  padding: 0 12px;
}
.carousel-slide-inner {
  aspect-ratio: 3/4;
  background: var(--bg-elevated);
  border-radius: 8px;
  overflow: hidden;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-slide-inner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.6) 100%);
}
.carousel-slide-inner svg { width: 48px; height: 48px; opacity: 0.2; }
.carousel-label {
  position: absolute;
  bottom: 16px;
  left: 16px;
  right: 16px;
  z-index: 2;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--white);
  letter-spacing: 0.04em;
}
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 1px solid var(--gray-700);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-btn svg { width: 20px; height: 20px; }
.carousel-dots {
  display: flex;
  align-items: center;
  gap: 8px;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-700);
  border: none;
  transition: all var(--transition);
  cursor: pointer;
  padding: 0;
}
.carousel-dot.active {
  background: var(--red);
  width: 24px;
  border-radius: 4px;
}

/* ===== NEWSLETTER ===== */
.newsletter-section {
  background: var(--bg-secondary);
  border-top: 1px solid var(--gray-800);
  border-bottom: 1px solid var(--gray-800);
}
.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 48px;
}
.newsletter-text h3 {
  font-size: 1.6rem;
  margin-bottom: 8px;
}
.newsletter-text p {
  color: var(--gray-400);
  font-size: 0.95rem;
}
.newsletter-form {
  display: flex;
  gap: 12px;
  flex: 0 0 auto;
}
.newsletter-form input {
  font-family: var(--font-body);
  font-size: 0.95rem;
  padding: 14px 20px;
  background: var(--bg-primary);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  color: var(--white);
  width: 320px;
  min-height: 48px;
  transition: border-color var(--transition);
}
.newsletter-form input:focus {
  outline: none;
  border-color: var(--red);
}
.newsletter-form input::placeholder { color: var(--gray-500); }
.newsletter-form .form-group { position: relative; }
.newsletter-error {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  font-size: 0.8rem;
  color: var(--red);
  margin-top: 4px;
}
.newsletter-success {
  display: none;
  align-items: center;
  gap: 8px;
  font-size: 0.95rem;
  color: #22c55e;
  font-weight: 500;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-primary);
  padding: 80px 0 40px;
  border-top: 1px solid var(--gray-800);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; }
.footer-brand p {
  color: var(--gray-500);
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 280px;
}
.footer h4 {
  font-size: 0.85rem;
  letter-spacing: 0.12em;
  margin-bottom: 20px;
  color: var(--white);
}
.footer-links a {
  display: block;
  color: var(--gray-500);
  font-size: 0.9rem;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--white); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid var(--gray-800);
  font-size: 0.85rem;
  color: var(--gray-500);
}
.country-select {
  font-family: var(--font-body);
  background: var(--bg-secondary);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  color: var(--gray-300);
  padding: 8px 16px;
  font-size: 0.85rem;
  cursor: pointer;
  min-height: 40px;
}
.country-select:focus { outline: none; border-color: var(--red); }

/* ===== TOGGLE (Workout page) ===== */
.toggle-container { display: flex; justify-content: center; margin-bottom: 48px; }
.toggle-group {
  display: inline-flex;
  background: var(--bg-secondary);
  border: 1px solid var(--gray-800);
  border-radius: 6px;
  overflow: hidden;
}
.toggle-btn {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 14px 40px;
  background: transparent;
  color: var(--gray-400);
  transition: all var(--transition);
  min-height: 48px;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}
.toggle-btn:hover:not(.active) { color: var(--white); }

.toggle-content { display: none; animation: fadeIn 300ms ease; }
.toggle-content.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== SCHEDULE TABLE ===== */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}
.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  text-align: left;
  padding: 16px 24px;
  border-bottom: 2px solid var(--gray-800);
}
.schedule-table tbody td {
  padding: 18px 24px;
  border-bottom: 1px solid var(--gray-800);
  color: var(--gray-300);
}
.schedule-table tbody tr:hover { background: rgba(230, 57, 70, 0.05); }
.schedule-table .day-name {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  text-transform: uppercase;
  color: var(--white);
}
.schedule-table .muscle-tag {
  display: inline-block;
  background: rgba(230, 57, 70, 0.1);
  color: var(--red);
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 12px;
  border-radius: 4px;
}

/* ===== INSTRUCTOR GRID ===== */
.filter-bar {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 10px 24px;
  background: transparent;
  color: var(--gray-400);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  transition: all var(--transition);
  min-height: 44px;
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--gray-700);
  transform: translateY(-4px);
}
.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-elevated), #2a1215);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.instructor-photo::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.5) 100%);
}
.instructor-photo svg { width: 48px; height: 48px; opacity: 0.25; }
.instructor-info { padding: 20px; }
.instructor-info h3 {
  font-size: 1.1rem;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.instructor-info .location {
  font-size: 0.85rem;
  color: var(--gray-500);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.instructor-info .location svg { width: 14px; height: 14px; }
.instructor-info .btn { width: 100%; font-size: 0.8rem; padding: 10px; }
.instructor-card.hidden {
  display: none;
}

/* ===== FAQ ACCORDION ===== */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--gray-800);
}
.faq-question {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--white);
  background: none;
  width: 100%;
  text-align: left;
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: color var(--transition);
  min-height: 48px;
}
.faq-question:hover { color: var(--red); }
.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
  color: var(--gray-500);
}
.faq-item.active .faq-question svg { transform: rotate(45deg); color: var(--red); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 0 24px;
  color: var(--gray-400);
  line-height: 1.7;
}

/* ===== FEATURES (Digital page) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  padding: 40px 32px;
  transition: all var(--transition);
  position: relative;
}
.feature-card:hover {
  border-color: var(--gray-700);
  transform: translateY(-2px);
}
.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(230, 57, 70, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}
.feature-icon svg { width: 28px; height: 28px; color: var(--red); }
.feature-card h3 { font-size: 1.2rem; margin-bottom: 12px; }
.feature-card p { color: var(--gray-400); line-height: 1.7; font-size: 0.95rem; }

/* ===== METHOD OVERVIEW ===== */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.method-text h2 { font-size: clamp(2rem, 3.5vw, 3rem); margin-bottom: 20px; }
.method-text p { color: var(--gray-400); line-height: 1.7; margin-bottom: 24px; }
.method-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 32px;
}
.stat-item { text-align: center; }
.stat-number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--red);
  line-height: 1;
}
.stat-label {
  font-size: 0.8rem;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 4px;
}
.method-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1a0a0c, var(--bg-elevated));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.method-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, var(--red-glow), transparent 70%);
  border-radius: 8px;
}

/* ===== TOGGLE CONTENT CARDS ===== */
.toggle-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.toggle-card-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--bg-elevated), #2a1215);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.toggle-card-visual svg { width: 64px; height: 64px; opacity: 0.3; }
.toggle-card-text h3 { font-size: 1.8rem; margin-bottom: 16px; }
.toggle-card-text p { color: var(--gray-400); line-height: 1.7; font-size: 1.05rem; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta .btn-ghost { display: none; }
  .nav-hamburger { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--gray-800);
    padding: 24px;
    gap: 16px;
    z-index: 999;
  }

  .hero { min-height: 70vh; }
  .section { padding: 64px 0; }

  .community-section,
  .studio-grid,
  .two-ways-grid,
  .method-grid,
  .toggle-card { grid-template-columns: 1fr; gap: 32px; }

  .instructor-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .features-grid { grid-template-columns: 1fr; }

  .carousel-slide { min-width: 80%; }

  .newsletter-inner { flex-direction: column; text-align: center; gap: 24px; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .newsletter-form input { width: 100%; }

  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }

  .trial-section { padding: 80px 0; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 2.5rem; }
  .carousel-slide { min-width: 90%; }
  .method-stats { grid-template-columns: repeat(3, 1fr); gap: 12px; }
  .stat-number { font-size: 1.8rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
  .carousel-track { transition: none; }
}

:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-elevated: #222222;
  --bg-card: #1c1c1c;
  --red: #E63946;
  --red-dark: #c5303c;
  --red-glow: rgba(230, 57, 70, 0.25);
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #2a2a2a;
  --font-heading: 'Barlow Condensed', sans-serif;
  --font-body: 'Inter', sans-serif;
  --max-width: 1200px;
  --transition: 250ms ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--gray-300);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  font-weight: 700;
  text-transform: uppercase;
  color: var(--white);
  letter-spacing: 0.02em;
  line-height: 1.1;
}

/* ===== TOP PROMO BAR ===== */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 24px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--white);
  letter-spacing: 0.04em;
}
.promo-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 700;
}
.promo-bar a:hover { opacity: 0.85; }

/* ===== NAVBAR ===== */
.navbar {
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid var(--gray-800);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  font-weight: 900;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.nav-logo span { color: var(--red); }

.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--gray-400);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: var(--white); }
.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--red);
}

.nav-cta {
  display: flex;
  gap: 12px;
  align-items: center;
}

.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  padding: 8px;
}
.nav-hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 14px 32px;
  border-radius: 4px;
  transition: all var(--transition);
  min-height: 48px;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
}
.btn-primary:hover {
  background: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}
.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--bg-primary);
}
.btn-ghost {
  background: transparent;
  color: var(--gray-400);
  border: 1px solid var(--gray-700);
}
.btn-ghost:hover {
  border-color: var(--white);
  color: var(--white);
}
.btn-sm { padding: 10px 20px; font-size: 0.8rem; min-height: 40px; }
.btn-lg { padding: 18px 48px; font-size: 1.1rem; }

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: linear-gradient(135deg, var(--bg-primary) 0%, #1a0a0c 50%, var(--bg-primary) 100%);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, var(--red-glow) 0%, transparent 60%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 700px;
}
.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--red);
  border: 1px solid var(--red);
  padding: 6px 16px;
  margin-bottom: 24px;
}
.hero h1 {
  font-size: clamp(3rem, 7vw, 5.5rem);
  font-weight: 900;
  line-height: 0.95;
  margin-bottom: 24px;
}
.hero h1 .accent { color: var(--red); }
.hero p {
  font-size: 1.15rem;
  color: var(--gray-300);
  margin-bottom: 36px;
  max-width: 540px;
  line-height: 1.7;
}
.hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }

.hero-page {
  min-height: 50vh;
  background: linear-gradient(180deg, var(--bg-primary) 0%, #1a0a0c 100%);
}
.hero-page h1 { font-size: clamp(2.5rem, 5vw, 4rem); }

/* ===== SECTION STYLES ===== */
.section {
  padding: 100px 0;
}
.section-dark { background: var(--bg-secondary); }
.section-header {
  text-align: center;
  margin-bottom: 64px;
}
.section-header h2 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 1.05rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
}
.section-label {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--red);
  margin-bottom: 12px;
}

/* ===== COMMUNITY PROMO ===== */
.community-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.community-image {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--bg-elevated) 0%, #2a1215 100%);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.community-image::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 1px solid rgba(230, 57, 70, 0.15);
  border-radius: 8px;
}
.community-image svg {
  width: 80px;
  height: 80px;
  opacity: 0.3;
}
.community-text h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 20px;
}
.community-text p {
  color: var(--gray-400);
  font-size: 1.05rem;
  margin-bottom: 32px;
  line-height: 1.7;
}

/* ===== TWO WAYS ===== */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: var(--gray-700); }
.way-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(230, 57, 70, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}
.way-card-icon svg { width: 28px; height: 28px; color: var(--red); }
.way-card h3 { font-size: 1.6rem; margin-bottom: 16px; }
.way-card p {
  color: var(--gray-400);
  line-height: 1.7;
  margin-bottom: 28px;
}

/* ===== STUDIO EXPERIENCE ===== */
.studio-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.studio-visual {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #1a0a0c, var(--bg-elevated));
  border-radius: 8px;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.studio-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, var(--red-glow), transparent 70%);
}
.studio-visual svg { width: 64px; height: 64px; opacity: 0.4; position: relative; z-index: 1; }
.studio-text h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 20px;
}
.studio-text p { color: var(--gray-400); line-height: 1.7; margin-bottom: 32px; }

/* ===== FREE TRIAL CTA ===== */
.trial-section {
  background: linear-gradient(135deg, #2a0a0e 0%, var(--bg-primary) 50%, #1a0a0c 100%);
  text-align: center;
  padding: 120px 0;
  position: relative;
}
.trial-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--red-glow), transparent 60%);
  pointer-events: none;
}
.trial-content {
  position: relative;
  z-index: 1;
}
.trial-section h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 900;
  margin-bottom: 20px;
}
.trial-section p {
  font-size: 1.1rem;
  color: var(--gray-400);
  margin-bottom: 40px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== CAROUSEL ===== */
.carousel-section { overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  transition: transform 500ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.carousel-slide {
  min-width: 33.333%;
  padding: 0 12px;
}
.carousel-slide-inner {
  aspect-ratio: 3/4;
  background: var(--bg-elevated);
  border-radius: 8px;
  overflow: hidden;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-slide-inner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.6) 100%);
}
.carousel-slide-inner svg { width: 48px; height: 48px; opacity: 0.2; }
.carousel-label {
  position: absolute;
  bottom: 16px;
  left: 16px;
  right: 16px;
  z-index: 2;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--white);
  letter-spacing: 0.04em;
}
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 1px solid var(--gray-700);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-btn svg { width: 20px; height: 20px; }
.carousel-dots {
  display: flex;
  align-items: center;
  gap: 8px;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-700);
  border: none;
  transition: all var(--transition);
  cursor: pointer;
  padding: 0;
}
.carousel-dot.active {
  background: var(--red);
  width: 24px;
  border-radius: 4px;
}

/* ===== NEWSLETTER ===== */
.newsletter-section {
  background: var(--bg-secondary);
  border-top: 1px solid var(--gray-800);
  border-bottom: 1px solid var(--gray-800);
}
.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 48px;
}
.newsletter-text h3 {
  font-size: 1.6rem;
  margin-bottom: 8px;
}
.newsletter-text p {
  color: var(--gray-400);
  font-size: 0.95rem;
}
.newsletter-form {
  display: flex;
  gap: 12px;
  flex: 0 0 auto;
}
.newsletter-form input {
  font-family: var(--font-body);
  font-size: 0.95rem;
  padding: 14px 20px;
  background: var(--bg-primary);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  color: var(--white);
  width: 320px;
  min-height: 48px;
  transition: border-color var(--transition);
}
.newsletter-form input:focus {
  outline: none;
  border-color: var(--red);
}
.newsletter-form input::placeholder { color: var(--gray-500); }
.newsletter-form .form-group { position: relative; }
.newsletter-error {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  font-size: 0.8rem;
  color: var(--red);
  margin-top: 4px;
}
.newsletter-success {
  display: none;
  align-items: center;
  gap: 8px;
  font-size: 0.95rem;
  color: #22c55e;
  font-weight: 500;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-primary);
  padding: 80px 0 40px;
  border-top: 1px solid var(--gray-800);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; }
.footer-brand p {
  color: var(--gray-500);
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 280px;
}
.footer h4 {
  font-size: 0.85rem;
  letter-spacing: 0.12em;
  margin-bottom: 20px;
  color: var(--white);
}
.footer-links a {
  display: block;
  color: var(--gray-500);
  font-size: 0.9rem;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--white); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid var(--gray-800);
  font-size: 0.85rem;
  color: var(--gray-500);
}
.country-select {
  font-family: var(--font-body);
  background: var(--bg-secondary);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  color: var(--gray-300);
  padding: 8px 16px;
  font-size: 0.85rem;
  cursor: pointer;
  min-height: 40px;
}
.country-select:focus { outline: none; border-color: var(--red); }

/* ===== TOGGLE (Workout page) ===== */
.toggle-container { display: flex; justify-content: center; margin-bottom: 48px; }
.toggle-group {
  display: inline-flex;
  background: var(--bg-secondary);
  border: 1px solid var(--gray-800);
  border-radius: 6px;
  overflow: hidden;
}
.toggle-btn {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 14px 40px;
  background: transparent;
  color: var(--gray-400);
  transition: all var(--transition);
  min-height: 48px;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}
.toggle-btn:hover:not(.active) { color: var(--white); }

.toggle-content { display: none; animation: fadeIn 300ms ease; }
.toggle-content.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== SCHEDULE TABLE ===== */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}
.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  text-align: left;
  padding: 16px 24px;
  border-bottom: 2px solid var(--gray-800);
}
.schedule-table tbody td {
  padding: 18px 24px;
  border-bottom: 1px solid var(--gray-800);
  color: var(--gray-300);
}
.schedule-table tbody tr:hover { background: rgba(230, 57, 70, 0.05); }
.schedule-table .day-name {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  text-transform: uppercase;
  color: var(--white);
}
.schedule-table .muscle-tag {
  display: inline-block;
  background: rgba(230, 57, 70, 0.1);
  color: var(--red);
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 12px;
  border-radius: 4px;
}

/* ===== INSTRUCTOR GRID ===== */
.filter-bar {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 10px 24px;
  background: transparent;
  color: var(--gray-400);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  transition: all var(--transition);
  min-height: 44px;
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--gray-700);
  transform: translateY(-4px);
}
.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-elevated), #2a1215);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.instructor-photo::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.5) 100%);
}
.instructor-photo svg { width: 48px; height: 48px; opacity: 0.25; }
.instructor-info { padding: 20px; }
.instructor-info h3 {
  font-size: 1.1rem;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.instructor-info .location {
  font-size: 0.85rem;
  color: var(--gray-500);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.instructor-info .location svg { width: 14px; height: 14px; }
.instructor-info .btn { width: 100%; font-size: 0.8rem; padding: 10px; }
.instructor-card.hidden {
  display: none;
}

/* ===== FAQ ACCORDION ===== */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--gray-800);
}
.faq-question {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--white);
  background: none;
  width: 100%;
  text-align: left;
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: color var(--transition);
  min-height: 48px;
}
.faq-question:hover { color: var(--red); }
.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
  color: var(--gray-500);
}
.faq-item.active .faq-question svg { transform: rotate(45deg); color: var(--red); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 0 24px;
  color: var(--gray-400);
  line-height: 1.7;
}

/* ===== FEATURES (Digital page) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--gray-800);
  border-radius: 8px;
  padding: 40px 32px;
  transition: all var(--transition);
  position: relative;
}
.feature-card:hover {
  border-color: var(--gray-700);
  transform: translateY(-2px);
}
.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(230, 57, 70, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}
.feature-icon svg { width: 28px; height: 28px; color: var(--red); }
.feature-card h3 { font-size: 1.2rem; margin-bottom: 12px; }
.feature-card p { color: var(--gray-400); line-height: 1.7; font-size: 0.95rem; }

/* ===== METHOD OVERVIEW ===== */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.method-text h2 { font-size: clamp(2rem, 3.5vw, 3rem); margin-bottom: 20px; }
.method-text p { color: var(--gray-400); line-height: 1.7; margin-bottom: 24px; }
.method-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 32px;
}
.stat-item { text-align: center; }
.stat-number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--red);
  line-height: 1;
}
.stat-label {
  font-size: 0.8rem;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 4px;
}
.method-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1a0a0c, var(--bg-elevated));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.method-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, var(--red-glow), transparent 70%);
  border-radius: 8px;
}

/* ===== TOGGLE CONTENT CARDS ===== */
.toggle-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.toggle-card-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--bg-elevated), #2a1215);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.toggle-card-visual svg { width: 64px; height: 64px; opacity: 0.3; }
.toggle-card-text h3 { font-size: 1.8rem; margin-bottom: 16px; }
.toggle-card-text p { color: var(--gray-400); line-height: 1.7; font-size: 1.05rem; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta .btn-ghost { display: none; }
  .nav-hamburger { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--gray-800);
    padding: 24px;
    gap: 16px;
    z-index: 999;
  }

  .hero { min-height: 70vh; }
  .section { padding: 64px 0; }

  .community-section,
  .studio-grid,
  .two-ways-grid,
  .method-grid,
  .toggle-card { grid-template-columns: 1fr; gap: 32px; }

  .instructor-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .features-grid { grid-template-columns: 1fr; }

  .carousel-slide { min-width: 80%; }

  .newsletter-inner { flex-direction: column; text-align: center; gap: 24px; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .newsletter-form input { width: 100%; }

  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }

  .trial-section { padding: 80px 0; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 2.5rem; }
  .carousel-slide { min-width: 90%; }
  .method-stats { grid-template-columns: repeat(3, 1fr); gap: 12px; }
  .stat-number { font-size: 1.8rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
  .carousel-track { transition: none; }
}

:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}
